using System.Reflection;
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow (compile-time data)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "100% tax rate")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal(
            (decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice",  DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity",   DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate",    DisplayName = "Tax rate below 0")]
    [DataRow(10.00, 1, 1.01, "taxRate",     DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(
                (decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (runtime data)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> ValidDiscountCases =>
    [
        [100.00m, 0m,     100.00m],  // no discount
        [100.00m, 10m,    90.00m],   // 10% off
        [100.00m, 50m,    50.00m],   // half off
        [100.00m, 100m,   0.00m],    // free
        [59.99m,  25m,    44.9925m], // fractional result
        [0.00m,   50m,    0.00m],    // zero price
    ];

    [TestMethod]
    [DynamicData(nameof(ValidDiscountCases))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return [100.00m, -1m];
            yield return [100.00m, 101m];
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases))]
    public void ApplyDiscount_WithOutOfRangePercent_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    // ───────────────────────────────────────────────
    //  FormatPrice – DynamicData from method source
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> FormatPriceCases()
    {
        yield return [10.5m,    "$",  "$10.50"];
        yield return [1000m,    "€",  "€1000.00"];
        yield return [0.99m,    "£",  "£0.99"];
        yield return [0m,       "$",  "$0.00"];
    }

    [TestMethod]
    [DynamicData(nameof(FormatPriceCases), DynamicDataSourceType.Method)]
    public void FormatPrice_WithCurrencySymbol_ReturnsFormattedString(
        decimal price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice(price, symbol);

        Assert.AreEqual(expected, result);
    }
}

